fn single_try_engage(&self, version, rnd, player, data, target_id, debug) -> Option<SinglePlanBattle>

// --- 242행: 이 engage 가 '타워 다이브'인가? ---
let in_tower = data.cache.game.entity(target_id)          // vtable +0x1f0, Option<&Entity>
                 .is_some_and(|t| tower_discipline::engage_requires_dive(player, data, t));
// 대상이 아예 없으면(null) in_tower = false 로 접힌다(블록 %26).

// --- 243행: 두 갈래로 battle 생성 ---
let mut battle = if in_tower {
    // --- 244행 ---
    let target = data.cache.game.entity(target_id)?;      // Try::branch 인라인. None 이면 즉시 return None
    // --- 245행 ---
    if !single_battle::single_tower_dive_is_viable(version, rnd, player, data,
                                                  &self.team_plan /*+0xf8*/, target, debug) {
        return None;                                      // 다이브가 불가하면 engage 자체를 포기
    }
    // --- 248행 ---
    let mut b = SinglePlanBattle::new_dive(version,
                     BattlePlanGoal::TryKill(target_id, 60), data, player);
    // --- 249행: 다이브할 타워를 고른다 ---
    b.dive_tower /*+0x8c*/ =
        data.cache.iter_towers_without_nexus(1 - player.info.team /*+0x930*/)
            // 반환 이터레이터(120B) = Chain< Flatten<array::IntoIter<Option<&Entity>, 6>>,
            //                              Copied<slice::Iter<&Entity>> >
            // 앞부분: 레인 타워 6칸(각 칸 Option, null=없음) — 본문에서 수동 전개돼 있다
            // 뒷부분(+104): 나머지 타워 슬라이스 — Copied::next 로 뽑는다
            .min_by_key(|t| {
                 let dx = abs_diff(t.x /*+0x660*/, target.x);
                 let dy = abs_diff(t.y /*+0x668*/, target.y);
                 dx*dx + dy*dy            // 제곱거리(부호없는 절대차. sqrt 없음)
             })
            .and_then(|t| match t.ty /*+0x68 태그*/ {
                 EntityType::Tower(tw) => Some(tw.ty /*+0x128, TowerType*/),
                 _ => None,               // i8 -1
             });
    // 타워가 하나도 없거나 최솟값이 없으면 dive_tower = None(-1)
    b                                     // 252행
} else {
    // --- 253행: 평범한 킬 시도 ---
    SinglePlanBattle::new(version, BattlePlanGoal::TryKill(target_id, 60), data, player)
};

// --- 255행: 만든 플랜을 그 자리에서 한 번 굴려 본다 ---
battle.update(version, rnd, player, data,
              &self.positioning_score /*+0x990*/, &self.team_plan /*+0xf8*/, debug);

// --- 256행: 굴려본 결과로 채택 여부 판정 ---
let committed = !matches!(battle.sub_goal /*+0x58 태그*/,
                          KitingBack(3) | RunAway(4) | End(7));

// --- 258행 ---
if committed { Some(battle) } else { /* battle.chats 드롭 */ None }

// 요약: '전투를 시뮬레이션해 보고 곧바로 물러남/종료로 떨어지면 이 engage 는 안 한다'
// 가 채택 게이트다. 다이브 경로는 그보다 앞서 single_tower_dive_is_viable 로 한 번 더 걸린다.
